use super::*;
use crate::money::{money, Money};

/// The same bearish view expressed three ways, so the trade-off is a table rather than an argument.
pub fn compare(price: Money, shares: i64, put_premium: Money, put_strike: Money, contracts: i64, etf_stake: Money) -> Vec<Exposure> {
    let cur = price.currency;
    vec![
        Exposure {
            vehicle: Vehicle::Naked,
            capital_at_risk: money((shares * price.minor) / 2, cur),
            // NO NUMBER. The price has no ceiling and inventing a bound here would invite somebody
            // to size against it.
            max_loss: None,
            max_gain: money(shares * price.minor, cur),
            needs_margin: true,
            note: "loss has no ceiling, and the broker closes it at the call price rather than when you are proved wrong",
        },
        Exposure {
            vehicle: Vehicle::Put,
            capital_at_risk: money(put_premium.minor * 100 * contracts, cur),
            max_loss: Some(money(put_premium.minor * 100 * contracts, cur)),
            max_gain: money(put_strike.minor * 100 * contracts - put_premium.minor * 100 * contracts, cur),
            needs_margin: false,
            note: "the most you can lose is what you paid — that is what the premium buys, and it expires whether or not you were right",
        },
        Exposure {
            vehicle: Vehicle::InverseEtf,
            capital_at_risk: etf_stake,
            max_loss: Some(etf_stake),
            max_gain: etf_stake,
            needs_margin: false,
            note: "no margin and a bounded loss, but it rebalances DAILY and drifts from the index over any longer horizon",
        },
    ]
}
